@js:
/*
搜索时，可输入@后加上条件进行筛选或者按要求排序。支持输入书籍id
目前可选条件有：完本，连载，3更 ，7更，30更，免费，精品，30万字，30-50万字，50-100万字，100-200万字，50万字，100万字，200万字
可选排序有：默认，更新，推荐，月票，收藏，字数
//解释：3更，指3天内有更新；30万字，指30万字以内；免费和精品无法同时起效；推荐，指按推荐票数量排序
//举例：“重生@免费”，“系统@30万字@免费”，“我的@月票@精品”
*/
if (/^\u200b|^：/.test(key)) {
	if (page==1) {
		result = gethd(qdturl+'/author/'+key.slice(1));} else {
			result='data:;base64,MQ,{"type":"lyc"}';}
			//作者搜索
			cache.putMemory('qdts',page);
	}
else if (/\d{5,}$/.test(key)) {
		let bkid = key.match(/\d+$/)[0];
		//跳详情页
		result = 'http://127.0.0.1/qdzs/'+bkid;
		}
else if (/^@@/.test(key)) {
	cache.putMemory('qdts',page*1000);
	if (page==1)
	result = QDSign("v1/booksearch/autocomplete",["siteId=1","keyword="+key.slice(2),"count=20"]);
	else result='data:;base64,QQ,{"type":"lyc"}';
}
else if (/^@/.test(key)) {
	//角色
	cache.putMemory('qdts',0);
	result=QDSign("v2/booksearch/searchRoleBooks",["pageIndex="+page,"roleName="+key.slice(1),"pageSize=10"]);
} else {
cache.putMemory('qdts',0);
let sz = key.split("@");
//带符号可使自动排序失效
let kk = sz.shift().replace(/^[#＃]/,'');
let re = ['keywordType=1','siteId=1','keyword='+kk,'pageIndex='+page,'pageSize=20'];

let book_zt = book_px = "";
book_zt = sz.includes("完本")
? "actionstatus=1,"
:sz.includes("连载")
? "actionstatus=2,"
:sz.includes("3更")
? "actionstatus=3,"
:sz.includes("7更")
? "actionstatus=4,"
:sz.includes("30更")
? "actionstatus=5,"
:""
book_zt += sz.includes("200万字")
? "wordscount=1,"
:sz.includes("100万字")
? "wordscount=2,"
:sz.includes("50万字")
? "wordscount=3,"
:sz.includes("100-200万字")
? "wordscount=4,"
:sz.includes("50-100万字")
? "wordscount=5,"
:sz.includes("30-50万字")
? "wordscount=6,"
:sz.includes("30万字")
? "wordscount=7,"
:""
book_zt += sz.includes("免费")
? "paidmode=1,"
:sz.includes("精品")
? "paidmode=3,"
:""
book_px = sz.includes("默认")
? "=11"
:sz.includes("更新")
? "=1"
:sz.includes("推荐")
? "=2"
:sz.includes("月票")
? "=4"
:sz.includes("收藏")
? "=3"
:sz.includes("字数")
? "=6"
:""
book_px=="" ? '' : re.push("order"+book_px);
book_zt=="" ? '' : re.push("filters="+book_zt.slice(0,-1));

result = QDSign("v2/booksearch/searchbooks",re);}
Packages.java.lang.Thread.sleep(300);
result

